using Microsoft.EntityFrameworkCore;

// Cosmos DB context for the separate project with existing documents.
// Three EF Core 9 breaking changes require explicit configuration:
//   1. Discriminator property renamed from "Discriminator" to "$type"
//   2. id property no longer embeds the discriminator value
//   3. Synchronous I/O now throws — all queries must be async
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Preserve the old "Discriminator" property name so existing
        // documents remain readable without a data migration.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Keep the EF Core 8 compound id format ("Session|<key>")
        // so point-reads against existing documents still resolve.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
}

// Fix 3: Synchronous Cosmos DB queries now throw.
// Replace all sync calls with async equivalents:
//
//   BEFORE (throws in EF Core 9):
//     var sessions = db.Sessions.ToList();
//     db.SaveChanges();
//
//   AFTER:
//     var sessions = await db.Sessions.ToListAsync();
//     await db.SaveChangesAsync();

